    H.state('epic-decomposed', 'waiting'),
    H.state('epic-done', 'terminal', 'success'),
    H.state('epic-incomplete', 'terminal', 'failure')
  );

const Heartbeat = H.kind('service-heartbeat')
  .data(z.object({ service: z.string() }))
  .states(
    H.state('beat-due', 'pending'),
