  export type RunName<K extends StepKind, M extends string> = K extends 'run' ? M : never;
  export type BlockName<K extends StepKind, M extends string> = K extends 'block' ? M : never;

  export interface Flow<In, P, St, X extends string, R extends string, B extends string> extends Named {
