  .supply(H.operator)
  .store(store)
  .handler(experimentFlow, {
    exits: { aWins: AWins, bWins: BWins, inconclusive: Inconclusive },
    during: { sample: Sampling, nextHour: BetweenSamples, decide: Deciding },
  });

