  .scheduler(scheduler)
  .clients(controlApi)
  .observers(
    slack.notifier('incident-slack', { webhookUrl: H.env('SLACK_INCIDENT_WEBHOOK'), lanes: [incidents] }),
    markdown.board({ path: './.harness/board.md' }),
  );

