const tenancyFlow = H.flow('tenancy-review')
  .input(tenancySchema)
  .step('usageReview', usageReview, (ctx) => ({ customerId: ctx.unit.attributes.customerId }))
  .step('summarize', tenancySummarizer, (ctx) => ({
