  .exit('agreed', (ctx) => ctx.steps.draftMove.move === 'accept')
  .exit('offerSent');

const vendorReplies = webhook.json('vendor-replies', {
  port: H.slot.port(1),
  path: '/vendor-replies',
  secret: H.env('VENDOR_WEBHOOK_SECRET'),
