  .handler(tenancyFlow, {
    exits: { reviewed: Customer },
    during: { usage: TenancyReviewing, summary: TenancyReviewing, decision: AwaitingUpsellDecision },
  })
  .on(reviewDue, { enter: DueForReview })
  .on(suspend, { enter: Suspended })
  .on(reinstate, { enter: Customer })
