  [...c.eligible].sort((a, b) => a.windowEndsAt - b.windowEndsAt)[0] ?? null);

const subscriptions = H.pool('subscriptions')
  .accounts([
    { account: subscriptionA, share: 0.8 },
    { account: subscriptionB, share: 0.8 },
    { account: subscriptionC, share: 0.6 },
