  .handler(heartbeatFlow, { opens: Checking, ends: { healthy: Healthy } })
  .runner(local.shell({ slots: 3 }));

const heartbeatFailed = H.trigger('heartbeatFailed', H.on.transition(heartbeats, { to: [Unhealthy] }))
