  .supply([
    linear.issues(Epic, { apiKey: linearKey, team: 'ENG', labels: ['epic'] }, (issue, supply) =>
      supply.create({
        attributes: { issueId: issue.identifier, title: issue.title, description: issue.description, priority: issue.priority },
      })),
  ])
  .store(linear.store(Epic, {
    apiKey: linearKey,
