  .ends(['delivered', 'dropped'], c => c.out.features.every(child => child.verdict === 'success') ? 'delivered' : 'dropped');

const healthCheck = H.command('healthCheck', ['./scripts/health-check.sh']);

const probeFlow = H.flow('serviceProbe')
